changeSet.sql:
ALTER TABLE zc_task
  ADD CONSTRAINT fk_zc_task_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_task
  ADD CONSTRAINT fk_zc_task_enrolment FOREIGN KEY (tenant_id, enrolment_id, member_id)
    REFERENCES zc_enrolment (tenant_id, id, member_id);
ALTER TABLE zc_task
  ADD CONSTRAINT fk_zc_task_member FOREIGN KEY (tenant_id, member_id)
    REFERENCES zc_member_reference (tenant_id, id);

ALTER TABLE zc_task_dependency
  ADD CONSTRAINT fk_zc_task_dependency_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_task_dependency
  ADD CONSTRAINT fk_zc_task_dependency_task FOREIGN KEY (tenant_id, task_id)
    REFERENCES zc_task (tenant_id, id);
ALTER TABLE zc_task_dependency
  ADD CONSTRAINT fk_zc_task_dependency_depends_on FOREIGN KEY (tenant_id, depends_on_task_id)
    REFERENCES zc_task (tenant_id, id);

ALTER TABLE zc_task_assignment_history
  ADD CONSTRAINT fk_zc_task_assignment_history_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_task_assignment_history
  ADD CONSTRAINT fk_zc_task_assignment_history_task FOREIGN KEY (tenant_id, task_id)
    REFERENCES zc_task (tenant_id, id);

rollback.sql:
DROP TRIGGER trg_zc_task_dependency_gate ON zc_task;
DROP TRIGGER trg_zc_task_touch ON zc_task;
DROP FUNCTION zc_task_dependency_gate();

changeSet.sql:
-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_task ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_task FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_task_tenant ON zc_task
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_task_dependency ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_task_dependency FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_task_dependency_tenant ON zc_task_dependency
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_task_assignment_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_task_assignment_history FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_task_assignment_history_tenant ON zc_task_assignment_history
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_work_queue_definition ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_work_queue_definition FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_work_queue_definition_tenant ON zc_work_queue_definition
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_task_tenant ON zc_task;
ALTER TABLE zc_task NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_task DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_task_dependency_tenant ON zc_task_dependency;
ALTER TABLE zc_task_dependency NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_task_dependency DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_task_assignment_history_tenant ON zc_task_assignment_history;
ALTER TABLE zc_task_assignment_history NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_task_assignment_history DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_work_queue_definition_tenant ON zc_work_queue_definition;
ALTER TABLE zc_work_queue_definition NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_work_queue_definition DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_task TO zc_app;
GRANT USAGE ON SEQUENCE zc_task_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_task_dependency TO zc_app;
GRANT USAGE ON SEQUENCE zc_task_dependency_id_seq TO zc_app;
GRANT SELECT, INSERT ON zc_task_assignment_history TO zc_app;
REVOKE UPDATE, DELETE, TRUNCATE ON zc_task_assignment_history FROM zc_app;
GRANT USAGE ON SEQUENCE zc_task_assignment_history_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_work_queue_definition TO zc_app;
GRANT USAGE ON SEQUENCE zc_work_queue_definition_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_task FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_task_id_seq FROM zc_app;
REVOKE ALL ON zc_task_dependency FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_task_dependency_id_seq FROM zc_app;
REVOKE ALL ON zc_task_assignment_history FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_task_assignment_history_id_seq FROM zc_app;
REVOKE ALL ON zc_work_queue_definition FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_work_queue_definition_id_seq FROM zc_app;
